configuration.jsScript:
// Public webhook envelope only. Workflow selection belongs to the switch node.
var envelope = typeof msg === 'string' ? JSON.parse(msg) : msg;
if (!envelope || typeof envelope !== 'object' || Array.isArray(envelope)) {
  throw new Error('kibana-webhook-ingress: expected a webhook object');
}
if (envelope.schema_version !== 1) {
  throw new Error('kibana-webhook-ingress: schema_version must be 1');
}
if (!envelope.payload || typeof envelope.payload !== 'object' || Array.isArray(envelope.payload)) {
  throw new Error('kibana-webhook-ingress: payload must be an object');
}
// Keep optional source trace data when downstream nodes replace msg.
// Do not copy the payload or arbitrary envelope fields into metadata.
var traceFields = ['rule_id', 'rule_name', 'alert_id', 'timestamp'];
for (var i = 0; i < traceFields.length; i++) {
  var field = traceFields[i];
  var value = envelope[field];
  if (typeof value === 'string' && value.trim()) {
    metadata['kibana_' + field] = value;
  }
}
return { msg: envelope, metadata: metadata, msgType: msgType, dataType: 'JSON' };

// Business mapping only: extract the first HTTP(S) subscription URL in text order.
// The next jsFilter drops messages without a URL before the adapter is invoked.
// Input is the validated envelope, selected by Route by workflow.
var payload = msg.payload;
var text = typeof payload.message_content === 'string' ? payload.message_content : '';
var candidates = text.match(/https?:\/\/[^\s<>"'`，。；！？、【】「」『』（）]+/gi) || [];
var url = '';
for (var i = 0; i < candidates.length; i++) {
  var candidate = candidates[i];
  // Remove prose punctuation and unmatched closing brackets (e.g. Markdown links),
  // while preserving balanced parentheses in a URL path and IPv6 host brackets.
  var previous;
  do {
    previous = candidate;
    candidate = candidate.replace(/[.,;!]+$/, '');
    var pairs = [['(', ')'], ['[', ']'], ['{', '}']];
    for (var j = 0; j < pairs.length; j++) {
      var open = pairs[j][0];
      var close = pairs[j][1];
      if (candidate.slice(-1) === close &&
          candidate.split(close).length > candidate.split(open).length) {
        candidate = candidate.slice(0, -1);
      }
    }
  } while (candidate !== previous);
  if (/^https?:\/\/[^\/?#]+(?:[\/?#]|$)/i.test(candidate)) {
    url = candidate.replace(/^https?:/i, function (scheme) { return scheme.toLowerCase(); });
    break;
  }
}

return {
  msg: {
    id: payload.subscription_id,
    body: { url: url }
  },
  metadata: metadata,
  msgType: msgType,
  dataType: 'JSON'
};
